function ListingSectionNavigation({ vendor, hasOffer, reviewCount }) {
  const [active, setActive] = useState("listing-overview");
  const nav = useRef(null);
  const sections = [
    ["listing-overview", "Overview"],
    ...(!vendor ? [["listing-packages", "Packages"]] : []),
    ...(!vendor && !hasOffer ? [["listing-availability", "Availability"]] : []),
    ...(!vendor ? [["listing-policies", "Policies"]] : []),
    ["listing-reviews", "Reviews"],
    ...(vendor ? [["vendor-services", "Services"]] : []),
  ];
  useEffect(() => {
    let frame;
    const ids = ["listing-overview", ...(!vendor ? ["listing-packages", ...(!hasOffer ? ["listing-availability"] : []), "listing-policies"] : []), "listing-reviews", ...(vendor ? ["vendor-services"] : [])];
    const update = () => {
      const threshold = (nav.current?.getBoundingClientRect().bottom || 180) + 60;
      const current = ids.filter((id) => {
        const section = document.getElementById(id);
        return section && section.getBoundingClientRect().top <= threshold;
      }).at(-1);
      setActive(current || ids[0]);
      frame = undefined;
    };
    const schedule = () => { if (frame === undefined) frame = requestAnimationFrame(update); };
    update();
    window.addEventListener("scroll", schedule, { passive: true });
    window.addEventListener("resize", schedule);
    return () => {
      window.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", schedule);
      if (frame !== undefined) cancelAnimationFrame(frame);
    };
  }, [vendor, hasOffer]);
  return (
    <nav ref={nav} className="cm-section-nav [.customer-marketplace.cm-detail-page_&]:[position:sticky] [.customer-marketplace.cm-detail-page_&]:top-[115px] [.customer-marketplace.cm-detail-page_&]:z-[10] [.customer-marketplace.cm-detail-page_&]:flex [.customer-marketplace.cm-detail-page_&]:items-stretch [.customer-marketplace.cm-detail-page_&]:gap-[32px] [.customer-marketplace.cm-detail-page_&]:[overflow-x:auto] [.customer-marketplace.cm-detail-page_&]:[border-block:1px_solid_#dfd4ce] [.customer-marketplace.cm-detail-page_&]:mt-[28px] [.customer-marketplace.cm-detail-page_&]:mx-0 [.customer-marketplace.cm-detail-page_&]:mb-[38px] [.customer-marketplace.cm-detail-page_&]:bg-[#faf8f5] [.customer-marketplace.cm-detail-page_&]:[scrollbar-width:thin] [.customer-marketplace.cm-detail-page_&_a]:flex [.customer-marketplace.cm-detail-page_&_a]:items-center [.customer-marketplace.cm-detail-page_&_a]:gap-[6px] [.customer-marketplace.cm-detail-page_&_a]:py-[20px] [.customer-marketplace.cm-detail-page_&_a]:px-[2px] [.customer-marketplace.cm-detail-page_&_a]:whitespace-nowrap [.customer-marketplace.cm-detail-page_&_a]:border-b-2 [.customer-marketplace.cm-detail-page_&_a]:border-b-[transparent] [.customer-marketplace.cm-detail-page_&_a]:text-[12px] [.customer-marketplace.cm-detail-page_&_a]:text-[#75645d] [.customer-marketplace.cm-detail-page_&_a:hover]:text-[#8c414e] [.customer-marketplace.cm-detail-page_&_a:hover]:[border-bottom-color:#8c414e] [.customer-marketplace.cm-detail-page_&_a:focus-visible]:text-[#8c414e] [.customer-marketplace.cm-detail-page_&_a:focus-visible]:[border-bottom-color:#8c414e] [.customer-marketplace.cm-detail-page_&_a[aria-current]]:text-[#8c414e] [.customer-marketplace.cm-detail-page_&_a[aria-current]]:[border-bottom-color:#8c414e] [.customer-marketplace.cm-detail-page_&_a[aria-current]]:font-semibold [.customer-marketplace.cm-detail-page_&_.cm-nav-enquiry]:ml-auto [.customer-marketplace.cm-detail-page_&_.cm-nav-enquiry]:text-[#8c414e] [.customer-marketplace.cm-detail-page_&_.cm-nav-enquiry]:gap-[8px] [.customer-marketplace.cm-detail-page_&_a_span]:py-0 [.customer-marketplace.cm-detail-page_&_a_span]:px-[5px] [.customer-marketplace.cm-detail-page_&_a_span]:rounded-[4px] [.customer-marketplace.cm-detail-page_&_a_span]:bg-[#f3ece7] [.customer-marketplace.cm-detail-page_&_a_span]:text-[10px] max-[1100.001px]:[.customer-marketplace.cm-detail-page_&]:top-[110px] max-[860.001px]:[.customer-marketplace.cm-detail-page_&]:mb-[28px] max-[860.001px]:[.customer-marketplace.cm-detail-page_&]:gap-[26px] max-[560.001px]:[.customer-marketplace.cm-detail-page_&]:gap-[24px] max-[560.001px]:[.customer-marketplace.cm-detail-page_&]:top-[106px]" aria-label="Listing sections">
      {sections.map(([id, label]) => (
        <a key={id} href={`#${id}`} aria-current={active === id ? "location" : undefined}>
          {label}{id === "listing-reviews" && reviewCount > 0 && <span>{reviewCount}</span>}
        </a>
      ))}
      <a className="cm-nav-enquiry" href="#listing-booking">Enquire now<ArrowUpRight size={14} aria-hidden="true" /></a>
    </nav>
  );
}

export function AvailabilityCalendar({ id }) {
  const [from, setFrom] = useState(() =>
    new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Kolkata" }),
  );
  const state = useMarketplace(`/services/${id}/availability?from=${from}`);
  return (
    <section className="cm-panel [.customer-marketplace_&]:border [.customer-marketplace_&]:border-[#e8dfd9] [.customer-marketplace_&]:rounded-[16px] [.customer-marketplace_&]:p-[24px] [.customer-marketplace_&]:mb-[20px] [.customer-marketplace_&]:bg-white [.customer-marketplace.cm-detail-page_&:where(:not(.cm-reservation))]:p-[32px] [.customer-marketplace.cm-detail-page_&:where(:not(.cm-reservation))]:rounded-[16px] [.customer-marketplace.cm-detail-page_&:where(:not(.cm-reservation))]:mb-[28px] [.customer-marketplace.cm-detail-page_#listing-availability_&_>_p]:text-[12px] [.customer-marketplace.cm-detail-page_#listing-availability_&_>_p]:text-[#75645d] max-[1100.001px]:[.customer-marketplace.cm-detail-page_&]:p-[24px] max-[560.001px]:[.customer-marketplace.cm-detail-page_&]:p-[22px]">
      <h2>Availability</h2>
      <label>
        Starting date
        <input
          type="date"
          value={from}
          onChange={(e) => {
            if (e.target.value) setFrom(e.target.value);
          }}
        />
      </label>
      <ReadState state={state} />
      {state.data && (
        <div className="cm-calendar [.customer-marketplace_&]:grid [.customer-marketplace_&]:grid-cols-[repeat(7,_minmax(0,_1fr))] [.customer-marketplace_&]:gap-[6px] [.customer-marketplace_&]:my-[18px] [.customer-marketplace_&]:mx-0 [.customer-marketplace_&_span]:py-[10px] [.customer-marketplace_&_span]:px-[4px] [.customer-marketplace_&_span]:block [.customer-marketplace_&_span]:text-center [.customer-marketplace_&_span]:text-[13px] [.customer-marketplace_&_[aria-disabled=true]]:bg-[#f0edeb] [.customer-marketplace_&_[aria-disabled=true]]:text-[#998d87] [.customer-marketplace_&_[aria-disabled=true]]:[text-decoration:line-through] [.customer-marketplace.cm-detail-page_&_span]:border [.customer-marketplace.cm-detail-page_&_span]:border-[#e8dfd9] [.customer-marketplace.cm-detail-page_&_span]:rounded-[6px]">
          {state.data.days.map((d) => (
            <span
              key={d.date}
              aria-disabled={!d.available}
              title={`${d.date}: ${d.reason || "Available to request"}`}
              aria-label={`${d.date}: ${d.reason || "Available to request"}`}
            >
              {d.date.slice(8)}
            </span>
          ))}
        </div>
      )}
      <p>
        Available dates can be requested. The server checks availability again
        when booking.
      </p>
    </section>
  );
}
